import java.util.ArrayList;
import java.util.ConcurrentModificationException;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class FailFastVsFailSafeDemo {
    public static void main(String[] args) {
        // 1. Fail-Fast Demonstration with ArrayList
        List<String> failFastList = new ArrayList<>(List.of("Node_1", "Node_2", "Node_3"));
        try {
            for (String node : failFastList) {
                if (node.equals("Node_1")) {
                    failFastList.add("Node_4"); // Structural mutation during loop!
                }
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("Fail-Fast Caught: " + e.getClass().getSimpleName());
        }

        // 2. Fail-Safe Demonstration with CopyOnWriteArrayList
        List<String> failSafeList = new CopyOnWriteArrayList<>(List.of("Node_1", "Node_2", "Node_3"));
        System.out.print("Fail-Safe Traversal: ");
        for (String node : failSafeList) {
            System.out.print(node + " ");
            if (node.equals("Node_1")) {
                failSafeList.add("Node_4"); // Mutates snapshot array cleanly!
            }
        }
        System.out.println();
        System.out.println("Fail-Safe Final List: " + failSafeList);
    }
}
// Expected Output:
// Fail-Fast Caught: ConcurrentModificationException
// Fail-Safe Traversal: Node_1 Node_2 Node_3 
// Fail-Safe Final List: [Node_1, Node_2, Node_3, Node_4]

