import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.NoSuchElementException;

public class ModCountContainer<E> implements Iterable<E> {
    private Object[] data = new Object[10];
    private int size = 0;
    private int modCount = 0; // Tracks structural mutations

    public void add(E element) {
        data[size++] = element;
        modCount++; // Increment on mutation
    }

    @Override
    public Iterator<E> iterator() {
        return new Iterator<>() {
            private int cursor = 0;
            private final int expectedModCount = modCount; // Capture snapshot

            @Override
            public boolean hasNext() {
                return cursor < size;
            }

            @SuppressWarnings("unchecked")
            @Override
            public E next() {
                if (modCount != expectedModCount) {
                    throw new ConcurrentModificationException("Structural modification detected!");
                }
                if (!hasNext()) throw new NoSuchElementException();
                return (E) data[cursor++];
            }
        };
    }

    public static void main(String[] args) {
        ModCountContainer<String> c = new ModCountContainer<>();
        c.add("A");
        c.add("B");

        Iterator<String> it = c.iterator();
        System.out.println("First: " + it.next()); // A

        c.add("C"); // Mutates modCount behind the iterator's back!

        try {
            it.next(); // Detects discrepancy and throws CME
        } catch (ConcurrentModificationException ex) {
            System.out.println("Verified fail-fast behavior: " + ex.getMessage());
        }
    }
}

