import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;

public class SetAllowedVerifier {
    public static boolean verifySetAllowedDuringIteration(List<String> list) {
        if (list == null || list.size() < 2) return false;
        try {
            Iterator<String> it = list.iterator();
            it.next();
            list.set(1, "updated"); // Non-structural modification
            it.next(); // Should NOT throw CME!
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public static void main(String[] args) {
        List<String> list = new ArrayList<>(List.of("old1", "old2"));
        System.out.println(verifySetAllowedDuringIteration(list));
    }
}

