import java.util.concurrent.CopyOnWriteArrayList;

public class CowCounter {
    public static int countVisited(CopyOnWriteArrayList<String> list) {
        if (list == null) return 0;
        int visited = 0;
        for (String item : list) {
            visited++;
            list.add("new_" + visited);
        }
        return visited;
    }

    public static void main(String[] args) {
        CopyOnWriteArrayList<String> cow = new CopyOnWriteArrayList<>();
        cow.add("1");
        cow.add("2");
        cow.add("3");
        System.out.println(countVisited(cow));
        System.out.println(cow.size());
    }
}
